    "summary" : "학점과 자격증은 있었지만 포트폴리오가 비어 있었어요. 프로젝트 · 해커톤 · AICON 경험으로 최종 합격했어요.",
    "body" : [ "학교 다닐 때 나름 학점 관리도 꼼꼼히 하고 정보처리기사 자격증도 미리 따뒀기 때문에 취업 서류 패스는 문제없을 줄 알았습니다. 그런데 웬걸, 막상 취업 시장에 던져지니 이력서의 '프로젝트 및 실무 경험' 란에 쓸 내용이 단 한 줄도 없는 거예요. 수업 시간에 제출했던 조별 과제 수준의 코드를 포트폴리오로 낼 수는 없는 노릇이니까요. 계속되는 서류 광탈에 멘붕이 왔을 때, '실전 프로젝트'에 목말라 인사교의 문을 두드렸습니다.", "인사교에서의 6개월은 제 텅 빈 이력서를 화려하게 채워준 황금 같은 시간이었습니다. 2~3번의 굵직한 팀 프로젝트는 물론이고, 온라인 AI 해커톤에 참여해 타 반 교육생들과 무박 2일로 결과물을 낸 경험, 그리고 AICON 2025 행사에 참여해 업계 동향을 파악했던 비교과 활동까지! 이력서에 녹여낼 수 있는 '진짜 스토리'들이 끝도 없이 쏟아졌습니다.", "면접장에 가보니 면접관님들은 제 학점보다, 인사교에서 진행했던 프로젝트 아키텍처와 트러블슈팅 경험에 훨씬 더 많은 관심을 보이셨습니다. \"해커톤에서 짧은 시간 안에 어떻게 의견 조율을 했나요?\", \"AI 모델을 웹에 연동하면서 어떤 오류를 겪었죠?\" 같은 질문들에 인사교에서 구르며 겪은 찐 경험들을 술술 풀어내니 결과는 당연히 최종 합격이었습니다! 전공 지식이라는 튼튼한 뼈대는 있지만, 거기에 살을 붙일 '포트폴리오'가 부족한 전공자분들이라면 인사교에서 그 퍼즐을 완벽하게 맞추실 수 있을 거예요!" ],
