    "summary" : "프로젝트 마감에 지쳐 있던 금요일 밤, 팀원들이 랩실에서 깜짝 생일 파티를 열어 줬어요.",
    "body" : [ "인사교 생활을 떠올리면 절대 잊을 수 없는, 제 인생 최고의 몽글몽글한 추억 하나를 공유하고 싶어요!", "바야흐로 날이 제법 쌀쌀해진 11월, 저희 팀은 코앞으로 다가온 프로젝트 마감 때문에 정규 수업이 끝난 후에도 다 같이 남아서 폭풍 작업을 하고 있었어요. 저녁때가 돼서 제가 \"다들 밥 먹으러 가자!\" 했는데, 팀원들이 짠 것처럼 \"입맛이 없다\", \"대충 때우련다\" 하면서 엄청 시큰둥한 반응을 보이는 거예요.", "속으로 '다들 너무 피곤하고 스트레스받아서 입맛이 없나 보다 ㅠㅠ' 싶어서, 출출할 때 같이 먹으려고 편의점에서 간단한 간식거리를 사서 강의실로 돌아왔죠. 그런데 강의실에 아무도 없는 거예요! 당황해서 혼자 앉아있는데 한 팀원한테서 \"할 이야기 있으니 랩실로 잠깐 와달라\"는 진지한 전화가 왔습니다.", "'뭐지? 무슨 문제라도 생겼나?' 하고 잔뜩 긴장해서 랩실 문을 열었는데... 세상에, 팀원들이 짠! 하고 생일 케이크를 들고 서 있는 거 있죠!", "알고 보니 제 생일이 바로 다가오는 일요일이었는데, 주말이라 학원에서 못 만나니까 금요일에 미리 깜짝 파티를 몰래 준비해 준 거였어요. (생일은 대체 어떻게 알았냐고 물어보니까 카톡 생일 알림 보고 알았대요 ㅋㅋㅋ)", "진짜 생각지도 못한 감동적인 서프라이즈에 눈물이 찔끔찔끔 났어요 ㅠㅠ 연일 계속되는 프로젝트 압박에 피곤하고 마음의 여유도 없었는데, 그 순간 힘들었던 게 정말 눈 녹듯 싹 날아가더라고요. 다 같이 둘러앉아 팀원들이 미리 시켜둔 피자를 나눠 먹는데 어찌나 맛있고 행복하던지!", "치열하고 힘든 과정 속에서도 서로를 챙겨주는 따뜻한 팀원들을 만난 덕분에, 인사교에서 평생 잊지 못할 몽글몽글하고 소중한 추억을 안고 갑니다!" ],
