    "cat" : "job",
    "summary" : "혼자 코드를 다 짜던 '독고다이'가 팀 프로젝트로 소통을 배웠고, 면접에서 합격을 직감했어요.",
    "body" : [ "학교 다닐 때 저는 철저한 '독고다이'형 학생이었습니다. 조별 과제를 하면 답답해서 차라리 혼자 밤새워 코드를 다 짜버리는 게 속 편했거든요. 그런데 막상 4학년이 되어 취업을 준비하려니, 모든 기업의 면접에서 '팀원들과의 협업 경험'이나 '의견 충돌을 해결해 본 경험'을 집요하게 묻더라고요. 혼자 에러를 잡는 법만 알았지, 남과 소통하며 일하는 법은 전혀 몰랐던 저에게 인사교는 완벽한 실전 커뮤니케이션 훈련소였습니다.", "인사교에서는 전공자와 비전공자가 자연스럽게 한 팀이 되어 프로젝트를 진행합니다. 처음엔 개발 용어 자체를 낯설어하는 팀원들에게 제 코드를 설명하고 설득하는 게 꽤 낯설고 어려웠어요. 하지만 매일 디스코드로 머리를 맞대고 회의하고, 깃헙(GitHub) 코드가 꼬였을 때 같이 화면을 보며 해결하고, 동명동 맛집에서 점심도 든든하게 챙겨 먹으며 부대끼다 보니 어느새 '비개발자의 언어로 기술을 쉽게 풀어서 설명하는 법'을 자연스럽게 터득하게 되었습니다.", "실제 취업 면접장에서 \"기획자나 디자이너 등 타 직군과 기술적인 문제로 소통해 본 적 있나요?\"라는 단골 압박 질문을 받았을 때, 저는 인사교에서 팀원들과 소통하며 기획과 개발의 타협점을 찾았던 경험을 아주 여유 있고 자신 있게 꺼낼 수 있었습니다. 면접관님께서 제 경험을 듣고 고개를 끄덕이셨을 때 합격을 직감했죠! 혼자 코드만 잘 치는 '코딩 머신'을 넘어, 현업에서 진짜 환영받는 '소통형 개발자 동료'로 레벨업하고 싶은 전공자분들께 인사교는 최고의 선택이 될 겁니다!" ],
