    "body" : [ "컴퓨터공학과 4학년 1학기 무렵, 저는 심각한 '코딩 권태기'에 빠져있었습니다. 매번 정해진 답을 찾는 과제와 중간/기말고사에만 치이다 보니, \"내가 진짜 개발을 좋아하는 게 맞나?\", \"웹, 앱, AI, 클라우드 중에 대체 내 적성은 뭐지?\" 하는 딜레마에 빠져 취업 준비는 엄두도 내지 못하고 있었죠. 그러다 분위기 전환이라도 해보자는 마음으로 인사교에 입교하게 되었습니다.", "결론부터 말하자면, 인사교는 잃어버렸던 제 코딩 열정에 다시 불을 지펴준 곳입니다! 학교에서는 경험하기 힘들었던 최신 기술 트렌드(AI, 클라우드 등)를 직접 만져보면서 \"아, 기술을 이렇게 응용하면 이런 서비스가 뚝딱 나오는구나!\" 하는 개발의 순수한 재미를 다시 깨닫게 되었거든요. 무엇보다 비전공자임에도 밤을 새워가며 열정적으로 코딩하는 동기들의 모습은, 전공자라는 타이틀에 안주하고 있던 제게 엄청난 긍정적 자극제가 되었습니다.", "게다가 단순히 찍어내기식 수업이 아니라, 강사님들과 끊임없이 소통하며 제가 어떤 파트(백엔드/클라우드 등)를 할 때 가장 눈이 반짝이는지 확실한 세부 진로를 찾을 수 있었어요. 방향성을 잃고 방황하던 전공자에서, 이제는 \"저는 이런 기술을 다루는 백엔드 개발자가 되겠습니다!\"라고 자신 있게 말하며 합격 목걸이를 거머쥘 수 있게 되었습니다. 저처럼 진로 방향성을 잃은 전공자분들께 인사교의 몰입 환경은 진짜 최고의 터닝포인트가 될 거라고 확신합니다!" ],
