    "title" : "결석 걱정을 줄여주는 수업 녹화본 지원!",
    "cat" : "life",
    "summary" : "늦게 합류했지만 매일 올라오는 줌 녹화본으로 놓친 기초 수업을 따라잡았어요.",
    "body" : [ "저는 개강을 이미 한 상태에서 뒤늦게 합류한 케이스라, 초반 '[공통] 기초과정' 실시간 수업을 통으로 놓쳐서 처음엔 꽤나 막막했어요. ( ºΔº )", "그런데 알고 보니 이곳은 매일매일 그날 진행된 수업의 줌(Zoom) 녹화본을 바로바로 업로드해 주시더라고요! 예전에 다른 부트캠프를 다닐 때는 다시보기 지원이 안 돼서 수강생들끼리 아쉬운 대로 따로 녹화하고 그랬거든요. 그런데 여기서는 기본 혜택으로 깔끔하게 제공해 주니까 정말 만족스러웠습니다.", "저처럼 중간에 합류한 사람은 물론이고, 갑자기 몸이 아파서 출석하지 못한 날이나 수업 중 놓친 부분을 복습하고 싶을 때 이 녹화본이 진짜 한 줄기 빛이 되어준답니다. 학원 생활하면서 누릴 수 있는 아주 쏠쏠하고 든든한 혜택이니 꼭 요긴하게 활용해 보세요!" ],
