    "id" : 48,
    "anchor" : "r-p48",
    "title" : "친구가 없어도 친해질 수 있다?",
    "cat" : "life",
    "summary" : "혼자 신청해 걱정했지만, 매일 함께하는 프로젝트 덕분에 I 성향인 저도 자연스럽게 친해졌어요.",
    "body" : [ "처음 신청하기 전 학교, 학과에서 혼자 신청하게 돼서 고민이 많아 검색 도중 유튜브에서 \"스마트미디어인재개발원인쌤TV\"를 찾아보았는데 수강자 후기에 친구가 없어도 친해진다는 내용을 보고 신청했습니다. 프로젝트를 매일 같이하다 보니 자연스럽게 친해지게 됩니다. 팀장도 팀원도 다들 같이 노력하다 보니 친해지게 됩니다, 저 같은 I 성향 사람도 친해졌으니 걱정 마세요. 다만 팀 프로젝트 하다가 고혈압이 오게 될 수도 있지만 좋은 팀원들 만나 극복하고 그러다 더 친해지게 되었습니다. 프로젝트 기간에 남아서 작업하다가 같이 저녁도 먹고 산책도 하고" ],
    "cohort" : 6,
