    "id" : 37,
    "anchor" : "r-p37",
    "title" : "내가 기획부터 AWS 배포까지 할 수 있다니..!!",
    "cat" : "proj",
    "summary" : "비전공자도 팀을 이뤄 기획부터 인공지능 서비스 개발, AWS 배포까지 전 과정을 해냈어요.",
    "body" : [ "6개월이라는 과정 속에서 제 실력을 가장 확실하게 끌어올려 준 건 단연 '2번의 실전 팀 프로젝트'였습니다! 사실 비전공자 입장에서는 혼자서 제대로 된 프로젝트를 기획하고 진행하는 게 거의 불가능에 가깝잖아요? 그런데 이곳에서는 뜻이 맞는 동기들과 팀을 이뤄 프로젝트 전체 과정을 직접 부딪히며 해낼 수 있다는 게 최고의 장점이었어요.", "물론 짧은 기간 안에 인공지능과 클라우드를 모두 다루다 보니, 클라우드 이론을 아주 깊게 파고들기엔 한계가 있을 수 있어요. 하지만 우리가 직접 아이디어를 내서 인공지능 서비스를 만들고, AWS를 활용해 실제 서비스 배포까지 완성해보는 전체 사이클을 경험할 수 있었기 때문에 전혀 아쉽지 않았습니다. 역시 강의만 듣는 것보다, 팀원들과 머리를 맞대고 프로젝트를 진행할 때 실력이 제일 빨리 성장하더라고요!", "비전공자가 80% 정도라 다들 처음엔 조금 어려워하기도 했지만, 마치 고등학교 시절로 돌아간 것처럼 반 친구들과 다 같이 \"으쌰으쌰\" 파이팅 하는 분위기라 전혀 힘들지 않았어요. 치열하게 공부하고 동기들과 재밌게 프로젝트에 몰두하다 보니 어느새 실무 역량도 쌓고 취업에 한 걸음 다가간 느낌이랄까요? ㅎㅎ", "혼자서는 막막한 프로젝트 경험을 든든한 팀원들과 함께 제대로 쌓고 싶으시다면, 너무 어렵게 고민하지 마시고 꼭 도전해 보시는 걸 추천합니다!" ],
    "cohort" : 5,
    "author" : "유**",
    "tags" : [ 0, 5 ]
