    "id" : 36,
    "anchor" : "r-p36",
    "title" : "독학으로는 불가능한 실전 팀 프로젝트 경험, 제대로 챙겨갑니다!",
    "cat" : "proj",
    "summary" : "혼자서는 절대 얻지 못했을 팀 프로젝트 경험이에요. 막히면 언제든 선생님께 물어 해결했어요.",
    "body" : [ "프론트엔드 개발자를 꿈꾸며 JS 트랙으로 입교해 무사히 수료를 마쳤습니다! 여러 장점이 있지만, 제가 이곳에서 얻은 가장 값진 수확은 혼자서 공부했다면 절대 얻지 못했을 '팀 프로젝트 경험'이에요.", "같은 목표를 향해 달려가는 열정적인 동기들과 팀을 이뤄 협업하고, 프로젝트를 진행하며 막히는 부분은 언제든 든든한 선생님들께 질문해 해결해 나가는 과정 자체가 실무와 가장 맞닿아 있는 귀중한 경험이었습니다.", "혼자서 어떻게 개발 공부를 시작해야 할지 모르겠거나, 협업을 통한 제대로 된 프로젝트 결과물이 없어 막막하신 분들께 정말 강력하게 추천드립니다! :)" ],
    "cohort" : 5,
