    "id" : 28,
    "anchor" : "r-p28",
    "title" : "수료 후 비로소 보이는 것들, 한 걸음 더 나아가기 위한 기록",
    "cat" : "path",
    "summary" : "정보처리기사, 포트폴리오 기록, SQLD, 외부 기관 활용까지. 수료 뒤 입사 지원을 하며 깨달은 것들이에요.",
    "body" : [ "수료 후 본격적으로 입사 지원을 시작하면서, 앞으로 어떤 준비를 더 해야 할지 진로와 취업에 대한 막막함이 참 컸습니다. 그 과정에서 직접 부딪히며 느끼고 깨달았던 현실적인 고민의 흔적들을 나누고자 합니다.", "1. \"내 이력서는 기업에게 충분한 경쟁력이 있을까?\" (정보처리기사의 뼈저린 필요성)", "취업 준비를 하며 가장 먼저 부딪힌 장벽은 '자격 요건'이었습니다. 입사하고 싶은 회사들을 찾아보니 지자체나 정부 부처와 협력하는 기업이 많았고, 생각보다 훨씬 많은 곳에서 '정보처리기사'를 필수나 우대 사항으로 요구하고 있었습니다. 막연한 취업 걱정과 불안감을 줄이기 위해서는 다른 무엇보다 정보처리기사 취득이 0순위로 해결되어야 할 과제라는 것을 깨달았습니다.", "2. \"나의 역량을 어떻게 증명할 수 있을까?\" (포트폴리오의 압박감)", "저를 가장 힘들게 했던 진로 고민 중 하나는 '나를 증명하는 포트폴리오'였습니다. 11월에 여러 가지 일이 겹쳐 수료 후에야 뒤늦게 포트폴리오를 작성하려다 보니 심리적인 압박감이 컸고 우여곡절도 많았습니다. 퀄리티에 대한 막막함을 줄이려면, 바쁘더라도 프로젝트 진행 과정에서 틈틈이 노션 같은 곳에 기록을 남겨두어야 한다는 것을 뒤늦게 실감했습니다.", "3. \"수많은 지원자들 사이에서 어떻게 차별화를 둘까?\" (SQLD 자격증)", "프론트엔드를 비롯한 다른 직무를 준비하면서도 '나만의 무기'를 어떻게 만들지 고민이 많았습니다. 채용 공고들을 유심히 분석해 보니, 의외로 절반 이상의 회사에서 직무를 불문하고 DB(데이터베이스) 활용 능력을 원하고 있었습니다. 이력서에 SQLD 같은 DB 관련 자격증 하나만 더 있어도, 진로의 폭이 넓어지고 남들보다 훨씬 눈에 띄는 지원자가 될 수 있겠다는 명확한 방향성을 얻게 되었습니다.", "4. \"이 불안한 취업 준비, 어떻게 덜어낼 수 있을까?\" (다양한 기관의 적극적인 활용)", "사관학교 내에서도 취업 컨설팅과 모의 면접 등 훌륭한 지원을 받았지만, 취업에 대한 불안감을 해소하기 위해 외부 기관의 도움도 더 적극적으로 받아볼 걸 하는 아쉬움이 짙게 남습니다. 대학일자리센터나 청년일자리카페 같은 곳을 찾아가 다양한 전문가의 시선을 빌렸다면, 진로에 대한 시야가 훨씬 넓어지고 고민의 무게도 덜 수 있었을 것 같습니다.", "돌이켜보면 '그때 미리 준비할걸' 하는 아쉬움과 고민도 남지만, 체력적으로 힘든 줄도 모르게 즐겁게 배우며 순식간에 지나간 6개월이었습니다. 이 치열했던 고민의 시간들이 앞으로 나아갈 길의 단단한 밑거름이 될 것이라 생각하며, 과정 내내 고생해 주신 4기 선생님들께 깊은 감사를 드립니다." ],
    "cohort" : 4,
    "author" : "조**",
    "tags" : [ 6 ]
