    "anchor" : "r-p26",
    "title" : "수료하면 끝? 놉! 끝까지 멱살 잡고 취업시켜준 인사교 선생님들! 정말 감사합니다!",
    "cat" : "job",
    "summary" : "수료 뒤에도 자소서 첨삭부터 면접 멘탈 관리까지 선생님들이 끝까지 챙겨 주셔서 첫 출근을 했어요.",
    "body" : [ "솔직히 수료식 날까지만 해도 '이제 진짜 나 혼자 차가운 취업 야생에 던져졌구나' 싶어서 눈앞이 캄캄했습니다. 비전공자라 이력서에 쓸 IT 관련 스펙이라곤 인사교에서 진행했던 프로젝트가 전부였거든요. 그런데 수료가 끝이 아니었습니다! ㅋㅋㅋ 오히려 본격적인 취업 준비를 시작하면서 선생님들이랑 더 자주 연락하고 괴롭혔던(?) 것 같아요.", "혼자서 자소서를 쓸 때는 기술적인 부분을 어떻게 어필해야 할지 막막하기만 했는데, 인사교 선생님들과 1대1 피드백을 주고받으면서 제 투박했던 프로젝트 경험들이 실무 친화적이고 매력적인 포트폴리오로 싹 다듬어졌습니다. 특히 면접에서 \"비전공자인데 이 코드를 왜 이런 방식으로 짰나요?\" 같은 꼬리물기 질문이 들어올까 봐 엄청 쫄아있었거든요. 그때 선생님들께서 \"정답을 맞히려고 하지 말고, 네가 에러를 잡기 위해 밤새워 고민했던 그 과정 자체를 진솔하게 녹여내라\"며 멘탈까지 꽉 잡아주셨어요. 포기하고 싶을 때마다 이력서 첨삭부터 멘탈 케어까지 아낌없이 퍼주신 든든한 지원군들 덕분에 무사히 첫 출근 도장을 찍을 수 있었습니다!" ],
    "cohort" : 4,
