    "anchor" : "r-p25",
    "title" : "전공자라고 다 아는 거 아님 주의! '이론파'에서 '실전파'로 거듭난 취뽀 후기!",
    "cat" : "job",
    "summary" : "컴공 전공자도 AWS 배포와 실무 협업은 처음이었어요. 프로젝트 트러블슈팅 경험으로 면접을 뚫었어요.",
    "body" : [ "솔직히 컴공 전공자라서 \"내가 굳이 부트캠프를 6개월이나 더 들을 필요가 있을까?\" 고민을 꽤 했었습니다. 학교에서 C언어, 자료구조, 운영체제까지 4년 내내 굴렀으니까요. 그런데 막상 4학년이 되어 채용 공고를 열어보니, 우대사항에 적힌 AWS 배포, 최신 프레임워크 활용, CI/CD 경험 같은 건 학교에서 제대로 해본 적이 없더라고요. 제 깃허브에는 그저 까만 콘솔창에서 돌아가는 학점용 과제 코드들만 덩그러니 남아있었죠.", "그래서 진짜 '실무 경험'을 채우기 위해 인사교에 합류했고, 결과적으로 제 취업을 결정지은 신의 한 수가 되었습니다! 이론으로만 달달 외우던 데이터베이스를 실제 클라우드 서버에 연동해 보고, 팀원들과 프론트·백엔드를 나눠 하나의 온전한 웹 서비스를 배포해 보는 경험은 학교 과제와는 차원이 다른 '진짜 실전'이었거든요.", "나중에 면접에 갔을 때도 단순히 \"저 CS 지식 잘 압니다!\"가 아니라, \"프로젝트를 AWS에 배포하는 과정에서 이런 에러가 터졌는데, 배운 CS 지식을 바탕으로 이렇게 원인을 분석하고 해결했습니다\"라고 실무적인 트러블슈팅을 어필할 수 있었습니다. 면접관님들 눈빛이 달라지는 게 보이더라고요. ㅋㅋㅋ 이론은 알지만 실전 프로젝트 경험이 턱없이 부족해서 막막한 전공자분들이라면, 인사교에서 포트폴리오 퀄리티를 확 끌어올려 보시길 강력 추천합니다!" ],
    "cohort" : 4,
