    "id" : 24,
    "anchor" : "r-p24",
    "title" : "자격증 응시료 지원해주는데 안 챙기면 개손해!!",
    "cat" : "life",
    "summary" : "정처기 · 빅분기 · SQLD 응시료 지원에 AWS 특강, AICE 자격증까지. 이 혜택은 꼭 챙기세요.",
    "body" : [ "인사교 생활하면서 코딩 공부 말고도 정처기(정보처리기사), 빅분기(빅데이터분석기사), SQLD 같은 자격증 시험도 부지런히 봤는데요. 막상 여러 개를 보려니까 취준생 입장에서 은근히 응시료가 훅훅 나가서 부담이더라고요. ㅠㅠ", "그런데 여기서 빛을 발한 인사교의 꿀 혜택! 바로 자격증 시험 비용 지원이었습니다!! 진짜 지갑 사정까지 세심하게 챙겨주는 든든함에 너무 감동이었어요. 게다가 정규 수업 외에도 AWS 특강을 열어주시고, AICE 자격증도 희망 인원을 받아서 아낌없이 지원해 주셨답니다.", "진짜 인사교 다니면서 주어지는 자격증 시험 혜택 안 챙긴다? 그건 완전 '손해 손해 개손해'입니다!! ㅋㅋㅋ 학원에서 팍팍 밀어줄 때 망설이지 말고 무조건 다 도전해 보세요. 지원해 주는 좋은 혜택들이 정말 많으니까, 다음 기수분들은 하나도 빠짐없이 알차게 쏙쏙 다 뽑아 먹고(?) 수료하시길 강력 추천합니다!" ],
