    "id" : 19,
    "anchor" : "r-p19",
    "title" : "시도하면 기회가 옵니다!",
    "cat" : "class",
    "summary" : "나이 때문에 망설였던 비전공자였지만, 노트북 · 책 · 자격증 시험료까지 지원받으며 6개월을 해냈어요.",
    "body" : [ "나이도 있고 망설이다가 몇개월 흘려보내고 용기내서 인공사 신청 후 면접 보고 6개월 과정을 듣게 되었습니다. 아무것도 모르는 비전공자인 제가 과연 잘 해낼 수 있을까? 걱정하면서 엄청 떨렸는데 막상 부딪혀 보니 반 동료들, 인공사 선생님 전부 다 친절하고 착하시고 AI수업 뿐만 아니라 사람들에게 많이 배우고 좋은 시간 이였습니다 :) 수업자체는 비전공자인 제가 따라가기 좀 힘들다고 느꼈어요 ㅠㅠ (4기 여러분들은 꼭 입교 전에 앨리스 사전 공부를 완독!? 하시길 추천드립니다! 이거 안듣고 수업 참여했다가 많이 후회했습니다!", "앨리스 인강을 들었다면 충분히 수업 따라 갈 수 있어요) 6개월 과정을 듣고 2개의 프로젝트를 진행했음에도 제 스스로 공부를 많이 하지 못해 너무 아쉬운 느낌입니다... 더 배우고싶은데 벌써 끝이라니! 그리고 학교 자체에서 지원해주는것이 엄청 많아서 깜짝 놀랐습니다! 노트북, 책, 동아리, 자격증 시험료 등등 제가 직업학교 몇군대 다녀봤지만 이 정도로 지원 빵빵한 곳은 처음입니다! 지금은 취업준비중인데 학교에서 계속 1:1 멘토링과 취업관련 업체나 정보들을 계속 주면서 케어를 해주고 계십니다. 고민되시면 일단 지원 해보세요 공짜니깐!! 4기 여러분들 화이팅!" ],
    "cohort" : 3,
    "author" : "윤**",
