    "summary" : "'전공자도 어렵다'는 말에 고민만 하다 시간을 버렸어요. 겁먹지 말고 일단 배워 보세요.",
    "body" : [ "코딩을 배우기 전 여러 고민들이 있었지만 그런 건 하나도 도움이 안된다는 걸 깨닳았습니다. ‘코딩은 전공자들도 어렵다’, ‘ai는 전공자만 취직 가능하다’, ‘si는 몸만 상한다’, 이런말 무시하고 일단 배우세요. 자신의 노력과 적성이 성패를 좌우할 뿐입니다. 해보고 자기랑 안맞으면 안하면 됩니다. 자신의 노력과 적성은 생각도 안하고 국비학원 탓하는 사람들이 많습니다. 누구나 할 수는 없습니다. 단지 코딩이 적성에 맞는 사람이 고민하며 저처럼 시간 낭비하지 말았으면 하는 바램입니다. 또한 그 반대라도 무료교육 받다가 그만두면 그만이니까 일단 시작하세요. 자기랑 맞을지도 모르는데 겁주는 말에 고민하거나 포기하면 손해입니다." ],
