    "body" : [ "교육 기간동안 지속적으로 취업에 대한 컨설팅은 물론 이력서와 자기소개서에 대한 상담도 받을 수 있었습니다. 교육과정 중후반부터는 인공지능 및 다양한 분야의 개발자를 필요로 하는 기업들이 방문하였고, 해당 기업의 취업을 희망하는 학생들은 면접을 볼 수 있는 기회들을 가졌습니다. 이 이외에도 수료식 날에 취업 박람회가 개최되어 학생과 기업들 간 만날 수 있는 시간이 마련되었으며, 수료 이후에도 지속적으로 학생들이 취업할 수 있게끔 취업 컨설팅과 지원 가능한 기업 리스트들을 제공 받을 수 있었습니다." ],
