    "body" : [ "중반기, 후반기 프로젝트에 걸쳐 두 번의 팀 프로젝트를 진행하면서 배운 내용을 토대로 팀원들과 함께 AI모델과 웹을 개발을 진행하였습니다. 중반기 프로젝트에서는 학생들이 자율적으로 주제를 정하여 팀 프로젝트를 수행했습니다. 또한 후반기 프로젝트 때는 기업들과 연계하여 각 기업이 제시하는 주제로 프로젝트를 개발해 봄과 동시에 해당 기업에게서 프로젝트 관련 멘토링을 받을 수 있었으며, 인공지능 사관학교에서도 꾸준히 기술 지원을 받을 수 있었습니다." ],
