    "body" : [ "들을까 말까 한참을 고민하다가 신청하게 된 광주 인공지능 사관학교 교육과정!", "너무 부족한 코딩 실력과 6개월이라는 긴 교육 시간 때문에 걱정이 이만저만이 아니었는데요 교육은 담당 선생님들께서 비전공자라도 아무 걱정 없을 정도로 기초부터 탄탄하게 가르쳐주셔서 본인이 수업시간만이라도 집중해서 듣는다면 무리 없이 따라갈 수 있어요 짝궁도 본인과 어느정도 수준을 고려해서 배치하는걸로 알고 있어서 모르는건 짝궁에게 물어봐도 되고 선생님께 질문하면 친절히 알려주시더라구요 프로젝트 때는 기본적으로 5인을 한 팀으로 이뤄 진행을 하구요 이 프로젝트를 통해서 실력이 가장 많이 상승하는거 같아요 다만 아쉬운건 트랙을 여러개로 나뉜 것에 비해 특화 기술에 대한 교육 시간이 너무 짧다는게 아쉬웠구요 2차 프로젝트 때 진행한 기업 연계 프로젝트는 기업에 따라서 소통이 너무 힘들 수 있고 이미 정해진 주제를 가지고 기획에 많은 시간을 쏟고 프로젝트 평가 기준도 주제의 참신함에 대한 점수가 가장 높다거나 서비스트랙인데 인공지능 기술을 너무 중점적으로 보는 등 프로젝트 진행 방식이 아쉬웠어요" ],
