    "anchor" : "r-p12",
    "title" : "우물 안 개구리가 바로 나야 나...",
    "cat" : "job",
    "summary" : "전공자의 근자감이 현업 멘토님의 코드 리뷰에 박살 났어요. 그 덕분에 원하던 기업에 합격했어요.",
    "body" : [ "입교 전에는 솔직히 \"그래도 내가 전공잔데, 코딩은 웬만큼 치겠지?\" 하는 근자감(?)이 살짝 있었습니다. ㅋㅋㅋ 하지만 인사교에서 본격적으로 팀 프로젝트를 시작하고, 현업 멘토님들께 코드 리뷰를 받으면서 그 오만함이 기분 좋게 박살 났어요.", "그동안 학교 과제를 할 때는 저 혼자만 알아볼 수 있게, 일단 에러 없이 '돌아가기만 하면 끝'인 스파게티 코드를 짰었거든요. 그런데 멘토님들께서 \"실무에서 이렇게 변수명 짓고 코드 짜면 동료들한테 원성 듣는다\", \"여러 명이 협업할 땐 깃(Git) 브랜치 관리를 이렇게 체계적으로 해야 한다\"며 현업 기준의 매운맛 피드백을 아낌없이 부어주셨습니다. 학생 티를 못 벗던 제 코드가 현업자 멘토링을 거치며 진짜 '돈 받고 팔 수 있는 수준'으로 다듬어지는 걸 보며 엄청난 희열을 느꼈어요.", "게다가 열정 넘치는 비전공자 동기들과 팀 프로젝트를 진행하면서, 어려운 개발 용어를 상대방의 눈높이에 맞춰 쉽게 설명하고 타협점을 찾는 '진짜 소통 능력'을 기를 수 있었습니다. 실제로 취업 면접 때 \"비개발 직군과 의견 충돌이 생기면 어떻게 소통할 것인가?\"라는 단골 질문을 받았는데, 인사교에서 동기들과 머리를 맞대고 문제를 해결했던 경험을 생생하게 풀었더니 엄청난 플러스 요인이 되더라고요! 코딩 스킬업은 물론이고 실무형 협업 마인드까지 장착하게 해준 인사교 덕분에 원하던 기업의 사원증을 목에 걸 수 있었습니다!" ],
