    "cat" : "job",
    "summary" : "면접관이 궁금해한 건 전공이 아니라 프로젝트였어요. 모의 면접과 취업 컨설팅이 합격의 한 수였어요.",
    "body" : [ "비전공자라는 사실 때문에 이력서를 제출할 때마다 '전공자들에게 밀리면 어떡하지?'라는 압박감이 항상 컸습니다. 하지만 막상 면접장에 가보니 기업에서 정말 궁금해하는 건 제 출신 전공이 아니라 인사교에서 팀원들과 부딪히며 완성했던 2~3번의 실무 프로젝트 경험이었습니다. 기술적인 화려함보다 어떤 에러를 겪었고 팀원들과 어떻게 소통하며 해결했는지를 집요하게 물어보시더라고요.", "특히 인사교 수료 전후로 끈질기게 받았던 '모의 면접'과 취업 컨설팅이 합격의 신의 한 수였습니다. 현업자 멘토님들이 비전공자로서 받을 수 있는 압박 질문에 대한 방어 논리부터, 이력서에 쓰인 프로젝트의 핵심을 논리적으로 어필하는 방법까지 싹 교정해 주셨거든요. 덕분에 실전 면접에서는 잔뜩 쫄아있던 예전과 달리, 제가 짠 코드와 기획 의도를 당당하게 설명할 수 있었습니다. 까만 화면에 에러만 띄우던 코린이가 어엿한 IT 기업의 신입으로 출근하게 되다니, 끝까지 버티고 엉덩이 붙이고 앉아있길 정말 잘했다는 생각이 듭니다!" ],
