    "id" : 10,
    "anchor" : "r-p10",
    "title" : "쏟아지는 탈락 속, '자격증 혜택'과 '나만의 도메인'으로 뚫어낸 취업",
    "cat" : "job",
    "summary" : "연이은 탈락 끝에 원래 전공과 SQLD · 정보처리기사를 살리는 전략으로 바꿔 취업에 성공했어요.",
    "body" : [ "수료 직후 호기롭게 입사 지원을 시작했지만, 생각보다 높은 취업의 벽과 쏟아지는 탈락 소식에 멘탈이 바사삭 부서지던 시기가 있었습니다. \"역시 비전공자는 안 되나?\" 싶어 우울해할 때, 담임 선생님과 취업 지원 센터의 조언을 듣고 지원 전략을 완전히 바꿨습니다. 무작정 지원서를 흩뿌리기보단, 제가 가진 원래 전공(도메인) 지식과 인사교의 혜택으로 악착같이 따둔 SQLD와 정보처리기사 자격증을 우대해 주는 기업들을 집중적으로 파고든 거죠.", "결과는 대성공이었습니다! 면접관님들은 갓 수료한 주니어의 엄청난 코딩 스킬을 기대하기보다, 제 기존 전공 지식과 IT 기술을 접목하려는 융합적인 사고방식, 그리고 DB를 다룰 줄 아는 기본기(SQLD)를 굉장히 높게 평가해 주셨습니다. 쌩뚱맞은 전공이라며 쓸모없다고 생각했던 과거의 시간들이 인사교에서 배운 기술을 만나 저만의 강력하고 뾰족한 무기가 된 셈이에요. 취준 과정이 막막하다면 학원에서 지원해 주는 자격증 응시료 혜택과 1:1 컨설팅은 무조건 200% 활용하시길 바랍니다. 그게 진짜 합격을 가르는 치트키가 되니까요!" ],
