    "cat" : "proj",
    "summary" : "강사님 코드에 고개만 끄덕이던 제가, 팀원들과 직접 만든 AI 서비스가 실제로 돌아가는 걸 봤어요.",
    "body" : [ "수업을 들을 때는 강사님의 코드를 보며 '아~ 저렇게 하는 거구나' 하고 고개만 끄덕였지, 막상 백지상태에서 코드를 짜려니 눈앞이 깜깜했습니다. 그런데 인사교에서 팀원들과 기획부터 개발, 그리고 AWS를 활용한 배포까지 프로젝트의 전체 사이클을 직접 부딪혀보니 그제야 머릿속에 둥둥 떠다니던 파편화된 지식들이 하나로 연결되는 기분이었습니다.", "특히 우리가 직접 아이디어를 낸 인공지능 서비스가 실제 링크를 통해 작동하는 걸 두 눈으로 확인했을 때의 짜릿함은 아직도 잊을 수 없어요! 단순히 책만 보고 코드를 따라 치는 것과, 팀원들과 에러창을 붙잡고 밤을 새워가며 실제 구동되는 하나의 '서비스'를 만들어내는 건 차원이 다른 성장이었습니다. 비전공자의 두려움을 깨고 \"나도 무언가를 만들어낼 수 있다\"는 확실한 자신감을 얻은 순간이었어요." ],
