    "anchor" : "r-p8",
    "title" : "늦은 나이와 쌩뚱맞은 전공? 오히려 나만의 강력한 차별화 무기입니다",
    "cat" : "path",
    "summary" : "문과 전공에 늦은 나이였지만, 그 전공 지식이 오히려 프로젝트와 면접에서 저만의 무기가 됐어요.",
    "body" : [ "IT와는 전혀 상관없는 문과 계열 전공으로 졸업하고 다른 일을 하다가 뒤늦게 부트캠프에 합류했습니다. 초반에는 \"이 나이에 쌩신입으로 시작하는 게 맞나?\", \"그동안 다른 분야에서 보낸 내 20대가 너무 아깝다\"는 생각 때문에 진로에 대한 확신이 흔들렸습니다. 기존에 쌓아온 시간의 버튼을 아예 초기화하고 맨땅에서 다시 시작하는 기분이었거든요.", "그런데 프로젝트를 진행하면서 이 '쌩뚱맞은 전공'이 오히려 저만의 엄청난 차별점이 된다는 걸 깨달았습니다. 기술 자체는 다른 동기들보다 조금 서툴렀을지 몰라도, 제가 기존에 공부했던 분야(도메인 지식)를 살려서 아이디어를 내고 서비스 사용자의 입장을 분석하는 데는 훨씬 유리했거든요. 기술은 도구일 뿐, 결국 그 기술로 '어떤 분야의 문제를 해결할 것인가'가 핵심이었습니다.", "면접에서도 \"그동안의 시간이 아깝지 않냐\"는 질문에, 오히려 \"저의 이전 전공 지식과 IT 기술을 결합해 남들이 보지 못하는 시너지를 낼 수 있다\"고 당당하게 대답할 수 있었습니다. 실제로 IT 업계에는 다양한 산업군을 이해하는 융합형 인재를 원하더라고요. 과거의 경험은 절대 사라지는 게 아니라, 개발이라는 새로운 무기를 만나 더 날카로워지는 과정이라고 생각합니다. 늦었다고 불안해하기보단 내 과거의 경험을 어떻게 IT와 엮을지 기획해 보세요!" ],
