    "cat" : "life",
    "summary" : "아침을 거르고 온 날도 점심 전 간식 시간 덕분에 버텼어요. '과자 드세요~' 한마디가 최고의 힐링이었어요.",
    "body" : [ "인사교 생활을 하면서 정말 좋았던 소소한 행복 중 하나가 바로 '간식 제공'이었어요!", "제가 아침에 바빠서 밥을 거의 못 챙겨 먹고 오는데, 보통 점심시간 전에 센스 있게 간식을 딱 챙겨주시거든요. 이게 진짜 허기진 배를 달래주고 점심때까지 버틸 수 있게 해주는 생명수(?)이자 든든한 원동력이 된답니다. ㅋㅋㅋ", "원래 평소에는 과자에 별로 관심이 없었는데, 여기서 \"이거 신상 과자예요~\" 하면서 이것저것 주시는 걸 먹다 보니 왜 이렇게 맛있는 건지... 덕분에 뜻밖의 신상 과자 맛에 푹 빠져버렸어요.", "무엇보다 제일 킬링 포인트는 보조 강사님께서 \"여러분 과자 드세요~!\" 하고 외치실 때예요! 그 한마디가 떨어지기가 무섭게 반 학생들이 우르르 몰려가서 간식을 챙기는데, 그 풍경이 어찌나 귀여운지 몰라요ㅋㅋㅋㅋ 머리 아픈 코딩 공부 중에 이런 소소하고 정겨운 일상들이 참 힐링되고 좋았어요!" ],
