    "cat" : "life",
    "summary" : "충장로 · 동명동 맛집과 카페를 점심 메이트들과 도장 깨기 하던 게 하루하루의 낙이었어요.",
    "body" : [ "금강산도 식후경이라고! 인사교 생활에서 절대 빼놓을 수 없는 쏠쏠한 즐거움 중 하나가 바로 '먹거리'였어요! 학원이 위치한 충장로와 동명동 일대에는 유명한 맛집과 예쁜 카페들이 정말 많거든요.", "제가 광주 북구에 살아서 평소엔 이 동네로 나올 일이 별로 없었는데, 인사교를 다니면서 매일 점심 메이트들과 본격적인 맛집 탐방을 다녔답니다. ㅋㅋㅋ 아마 이 근방 가성비 좋은 식당이랑 디저트 맛집은 저희가 싹 다 쓸고 다녔을 거예요! 오전 내내 코딩하느라 머리를 쥐어짜다가도 점심시간만 되면 \"오늘은 어디 갈까?\" 하며 다 같이 눈이 반짝반짝해졌어요. 매일매일 점심시간이 기다려질 정도로 맛있고 행복한 추억이 가득했던 일상이었습니다!" ],
