    "cat" : "class",
    "summary" : "경제학을 전공한 졸업생이 Java부터 배워 전체 1등을 하고, 기관이 연계해 준 IT 기업에 취업했어요.",
    "body" : [ "4차산업혁명 핵심 키워드 융합과 연결 - 때는 바야흐로 2017년 3월, 따듯한 햇살이 비치고 봄바람이 불어와 누군가의 마음을 설레게 할 계절. 하지만 막 대학 졸업을 마친 저에게는 그 따듯한 봄마저도 누구보다 차갑게만 느껴졌습니다. 대한민국 청년실업률이 10%가 넘어선 현재 대학을 졸업하여도 취업이 힘든 사실에 누구보다도 따듯한 봄과 졸업은 달갑게 느껴지지만은 않았습니다. 게다가 경제학이라는 경상계열에 졸업한 저는 이공계열 보다 취업이 어렵다는 사실을 알고 있어 취업에 대한 고민의 나날 이였습니다.", "취업을 위해 시사에 대한 공부 중 스마트폰 과 미디어의 영향으로 시사정보를 알 수 있었는데 자주 나오는 가장 큰 이슈는 바로 4차산업혁명이였습니다. 4차산업혁명이라는 것이 도대체 무엇길래 이렇게 강조를 하는 것일까? 궁금함을 참지 못한 저는 4차산업혁명에 대해 알아보기 시작했습니다. 4차산업혁명에 대해 공부를 하게 되면서 점점 4차산업혁명에 대해 흥미를 가지게 되었고, 또 정식으로 배우고 싶다는 생각이 들게 되었습니다. 그렇지만 제가 아는 주위에서는 4차산업혁명에 대해서 공부를 하고 싶어도 어디서 배워야 할지 또 마땅히 가르쳐 주는 곳이 존재하지 않았습니다.", "그러던 중 우연히 버스정류장에 붙어있던 포스터 하나에 저도 모르게 눈이 갔습니다. 포스터에는 제가 관심 있는 4차산업혁명에 대해서 수업을 해준다는 내용이였습니다. 평소에 관심있는 분야였던 만큼 부푼 마음을 안고 포스터에 기재된 전화번호로 전화문의를 했습니다. 연구원 분께서 교육과정에 대해서 친절하고도 상세히 설명을 해준 덕분에 이 과정은 꼭 들어야겠구나 라는 확신이 들었습니다.", "한편으로는 교육과정이 비 전공자들을 위해 충분히 따라 올 수 있게 진행된다고 하였지만 경상계열로써 컴퓨터에 대해서는 한번 도 접해보지 못했던 내가 이 과정을 잘 수료할 수 있을까라는 생각과 5개월이라는 긴 시간 동안 해낼 수 있을까라는 걱정이 들었습니다. 하지만 오리엔테이션으로 수업하기에 앞서 원장님의 말씀이 나도 할 수 있다라는 자신감을 키우게 되었고 4차산업혁명이 융합과 연결이니 만큼 다른 사람과 함께 먼저 친해질 수 있도록 자기소개와 간단한 인사를 나누었습니다. 오랜만에 듣는 수업이였지만 대학교 첫 수업 때처럼 강렬하게 제 마음을 흥분시켜놓았습니다.", "수업을 듣게 되면서 앞에서 이끌어주시는 강사님과 뒤처질까 노심초사하며 항상 뒤에서 든든하게 지원해주시는 보조강사님 그리고 항상 응원해주는 같이 수업 듣는 연수생들 마지막으로 내 옆에서 항상 친절하게 도와주는 짝꿍(메이트 시스템) 덕분에 수업에 못 따라갈까 하는 저의 걱정은 눈 녹듯 사라졌습니다. 첫 Java라는 컴퓨터 프로그래밍 언어를 배우면서 어렵긴 했지만 도와주는 사람들 덕분에 당당히 전체 연수생 중에 5등을 할 수 있었고, 이 자신감을 토대로 Web에서는 비 전공자였지만 전체 연수생 중에 1등을 할 수 있었습니다.", "외아들로 태어나서 혼자가 편했던 저에게 팀 프로젝트를 통해서 협동심의 중요성을 일깨워 주었고, 팀원들과 프로젝트를 진행하면서 누구보다도 잊지 못할 추억을 만들어 주었습니다. 프로젝트를 진행하면서 많은 어려움에 부딪혔지만 협력을 통해 팀원과 어려움을 이겨나가면서 이로 인해 더욱 더 한 껏 성장할 수 있는 발판을 마련할 수 있었습니다. 아프리카에서는 이런 속담이 있습니다. ‘빨리 가려면 혼자가라 하지만 멀리 가려면 함께가라’. 빠르게 변화하는 4차산업혁명에서 변화에 맞추기 위해서는 혼자서 가기 보다는 팀원, 동료와 함께 한다면 더욱 힘차게 나아갈 수 있을 겁니다.", "저는 비전공자이기 때문에 이 수업을 듣더라도 IT에는 취업을 못 할 거라고 생각했습니다. 하지만 열심히 노력 하였고 이로 인해 기관에서 연계해준 IT기업에 당당히 취업을 할 수 있었습니다. 추후 저처럼 고민하고 있을 예비 연수생 여러분들에게 스마트미디어인재개발원 수업을 추천해주고 싶으며 꼭 이 말을 해주고 싶습니다. ‘여러분도 충분히 할 수 있습니다!’ 감사합니다." ],
    "cohort" : 3,
