    "title" : "진짜 빡셌지만 그만큼 확실했던 5개월! 강력 추천해요",
    "cat" : "class",
    "summary" : "쉴 틈 없는 5개월이었지만, 실전 포트폴리오 2개를 만들어 원하던 웹 개발자로 취업했어요.",
    "body" : [ "5개월 동안 정말 쉴 틈 없이 빠듯하게 배웠지만, 돌이켜보면 그만큼 얻어간 게 참 많은 수업이었어요!", "솔직히 \"그냥 한 번 해볼까?\" 하는 가벼운 마음으로 오시면, 엄청난 진도와 학습량에 멘붕(?)이 올 수도 있거든요. ㅎㅎ 그래서 수업을 들으실 거라면 어느 정도 단단히 각오하고 오시는 걸 추천드려요.", "하지만 힘들었던 만큼 확실한 결과물이 보장된다는 게 이 수업의 최고 장점이에요. 제일 든든했던 건 수료할 때쯤 완성도 높은 실전 프로젝트 포트폴리오가 2개나 나온다는 거였어요! 저도 수업 때 만든 이 포트폴리오들 덕분에 지금은 원하던 웹 개발자로 당당하게 취업했답니다.", "치열하게 공부하면서 같이 고생한 좋은 동료들도 많이 만나고, 개발자로서의 진짜 경쟁력을 쑥쑥 키울 수 있었던 너무 알찬 5개월이었어요. 확실하게 실력을 올리고 싶으신 분들이라면 꾹 참고 도전해 보시길 꼭 추천드립니다!" ],
