    "anchor" : "r-p3",
    "title" : "답답했던 진로 고민, 여기서 싹 해결했어요!",
    "cat" : "path",
    "summary" : "'이 길이 맞을까' 걱정이 산더미였는데, 체계적인 커리큘럼과 든든한 지원 덕분에 진로에 확신이 생겼어요.",
    "body" : [ "처음 시작하기 전까지만 해도 \"내가 과연 잘 따라갈 수 있을까?\", \"이 길이 진짜 내 길이 맞을까?\" 하면서 진로에 대한 걱정이 산더미였어요. ㅠㅠ", "근데 막상 딱 시작해 보니까, 커리큘럼이 엄청 체계적으로 잘 짜여 있어서 막연했던 불안감은 어느새 사라지고 차근차근 배우는 데만 집중할 수 있더라고요!", "무엇보다 좋았던 건, 단순히 기술만 가르쳐주고 끝나는 게 아니라 제가 앞으로 어떤 방향으로 나아가야 할지 진로 갈피를 잡는 데 진짜 큰 도움을 받았다는 거예요. 과정 내내 옆에서 든든하게 챙겨주시고 이끌어주신 덕분에, 끝이 안 보이던 진로 고민에 마침표를 딱! 찍고 앞으로 나아갈 확신을 얻었답니다.", "저처럼 '어떤 길로 가야 할지' 몰라서 막막하고 답답하신 분들이라면, 여기서 진짜 큰 힌트와 용기를 얻어가실 수 있을 거예요! 강력 추천합니다!!" ],
