    "title" : "기초 문법만 알던 저에게 실무 감각을 깨워준 최고의 수업이었습니다!",
    "cat" : "class",
    "summary" : "기초 문법만 알던 제가 Java · DB · 안드로이드 · AI로 이어지는 커리큘럼으로 실무 감각을 얻었어요.",
    "body" : [ "수강 전에는 파이썬과 C#의 기초 문법만 알 뿐, 이를 실제 프로젝트나 업무에 어떻게 적용해야 할지 전혀 감을 잡지 못하는 상태였습니다.", "하지만 이 수업은 자바(Java)를 시작으로 DB, 안드로이드, 인공지능(AI)까지 체계적으로 확장되는 커리큘럼을 통해 저의 고민을 완벽하게 해결해 주었습니다. 단편적인 문법 학습을 넘어, 배운 내용을 바탕으로 실무에 직접 접근하고 활용할 수 있는 실질적인 개발 역량을 키워주는 수업 방식이 가장 만족스러웠습니다.", "막연했던 프로그래밍이 손에 잡히는 기술로 바뀌면서 하루하루 배워가는 과정이 정말 재미있고 행복했습니다. 탄탄한 수업 덕분에 실무에 대한 자신감을 얻고 갑니다. 감사합니다!" ],
