    "cat" : "job",
    "summary" : "다른 업종에서 IT로 전향해 5개월 만에 취업했어요. 가장 큰 무기는 팀 프로젝트로 쌓은 협업 경험이었어요.",
    "body" : [ "다른 업종에서 일하다 IT로 전향을 결심하고 처음 등록했을 때만 해도 막막함이 컸습니다. 하지만 이곳에서의 5개월 덕분에, 현재는 탄탄한 기본기를 바탕으로 좋은 회사에 취업하는 목표를 이뤘습니다!", "처음엔 5개월이라는 시간이 결코 짧지 않다고 생각했지만, 자바(Java) 기초를 시작으로 자바 페스티벌, 1차 및 2차 실무 프로젝트까지 몰입하다 보니 시간이 어떻게 가는지 모를 정도로 훌쩍 지나갔습니다.", "특히 제 취업의 가장 큰 무기는 '팀 프로젝트를 통한 협업 경험'이었습니다. 실력 있는 강사님들의 체계적인 커리큘럼으로 기술적 역량을 키운 것은 물론, 팀원들과 동고동락하며 실무에서 가장 요구되는 소통 능력과 사회성을 함께 기를 수 있었던 것이 합격에 결정적인 도움이 되었습니다.", "막연했던 비전공자의 도전을 '성공적인 취업'으로 이끌어준 유익하고 즐거운 학원 생활이었습니다. 좋은 사람들과 함께 즐겁게 성장하며 취업 문까지 뚫게 되어 정말 감사합니다!" ],
